import Root from "./2Managing State/PPassingDataDeeply/Simplify"
import {HandleInput as Fundamental} from "./2Managing State/4zBaseConcept"
import Sub from "./subReLearn"
import Custom from "./customComponent"
import "./ReLearn.css"

import { useState } from "react"

export default function() {
  const [anjas, setAnjas] = useState("anjass")
  const [walawe, setWalawe] = useState("walawee")
  const mix = anjas + " " + walawe
  return <>
  {mix}
  </>
}

